//! The embedded `/vendor/` inventory, shared with canvas.
//!
//! [`VENDOR_ASSETS`] is generated by this crate's `build.rs` from the
//! *same* manifest-defined file tree canvas's build verifies
//! (`jinn-canvas/resources/vendor/`, pinned by `vendor-manifest.toml`),
//! with the identical sha256 pin gate. That makes served vendor bytes
//! byte-identical to canvas's without a dependency on the canvas
//! implementation crate — the inventory is shared at build time through
//! the files the manifest names, not at link time through a crate edge.
//!
//! The tests here re-verify the invariants from the test side: paths are
//! unique and traversal-free, and every row is under the size cap (the
//! Mermaid dist ships gzipped or not at all).

/// Mermaid's dist is committed gzipped (~1.6 MB) and never raw (~5.5 MB);
/// this is the regression guard on that rule.
pub const MAX_EMBEDDED_BYTES: usize = 2 * 1024 * 1024;

/// The generated vendor-asset table, built from the shared manifest by
/// `build.rs`.
mod generated {
    include!(concat!(env!("OUT_DIR"), "/vendor_assets.rs"));
}

pub use generated::{VENDOR_ASSETS, VendorAsset};

#[cfg(test)]
mod tests {
    #![allow(clippy::expect_used, reason = "test assertions need expect")]

    use super::{MAX_EMBEDDED_BYTES, VENDOR_ASSETS};

    #[rstest::rstest]
    #[test]
    fn every_asset_is_under_the_size_cap() {
        // Given the generated vendor inventory.
        // When checking each asset against the manifest's size rule.
        // Then no embedded file exceeds the cap — the Mermaid dist ships
        // gzipped or not at all.
        for asset in VENDOR_ASSETS {
            assert!(
                asset.bytes.len() <= MAX_EMBEDDED_BYTES,
                "{} embeds {} bytes, over the {MAX_EMBEDDED_BYTES} cap",
                asset.path,
                asset.bytes.len()
            );
        }
    }

    #[rstest::rstest]
    #[test]
    fn served_paths_are_unique_and_traversal_free() {
        // Given the generated vendor inventory.
        // When collecting every served path.
        // Then no path repeats, and none escapes its root (`..`, an
        // absolute form, or a backslash).
        let mut seen = std::collections::BTreeSet::new();
        for asset in VENDOR_ASSETS {
            assert!(
                seen.insert(asset.path),
                "duplicate served path: {}",
                asset.path
            );
            assert!(
                !asset.path.contains("..") && !asset.path.starts_with('/'),
                "served path escapes the vendor root: {}",
                asset.path
            );
            assert!(
                !asset.path.contains('\\'),
                "served path uses a backslash: {}",
                asset.path
            );
        }
        assert!(!seen.is_empty(), "the inventory must not be empty");
    }

    #[rstest::rstest]
    #[test]
    fn the_core_visualization_libraries_are_present() {
        // Given the generated vendor inventory.
        // When reading the served-path set.
        // Then the libraries saved artifacts reference by the skill's
        // template are all embedded.
        let paths: std::collections::BTreeSet<&str> =
            VENDOR_ASSETS.iter().map(|a| a.path).collect();
        for required in [
            "katex/katex.min.js",
            "katex/katex.min.css",
            "mermaid/mermaid.min.js",
            "chartjs/chart.umd.js",
            "three/three.module.min.js",
            "vue/vue.global.prod.js",
        ] {
            assert!(
                paths.contains(required),
                "vendor inventory is missing {required}"
            );
        }
    }

    #[rstest::rstest]
    #[test]
    fn the_authored_canvas_files_are_present() {
        // Given the generated vendor inventory.
        // When reading the served-path set.
        // Then the two authored files canvas's build appends after the
        // manifest rows — absent from the manifest itself — are in the
        // applets inventory too. Parity means the whole inventory; a saved
        // app referencing `/vendor/canvas.css` serves the same bytes a
        // live canvas server would.
        let paths: std::collections::BTreeSet<&str> =
            VENDOR_ASSETS.iter().map(|a| a.path).collect();
        for required in ["canvas.css", "canvas-telemetry.js"] {
            assert!(
                paths.contains(required),
                "vendor inventory is missing the authored file {required}"
            );
        }
        // And both ride as identity encoding — they are plain text, not
        // gzip-wrapped library dists.
        for asset in VENDOR_ASSETS {
            if asset.path == "canvas.css" || asset.path == "canvas-telemetry.js" {
                assert_eq!(asset.encoding, "identity", "{} is plain text", asset.path);
            }
        }
    }
}
